class R{String s(boolean P,String[]I){int N=71,B[]=new int[I.length],j=0,i=1024,z;for(var s:I){var a=s.split(",");B[j++]=new Integer(a[0])+N*new Integer(a[1]);}do{int b[]=new int[N*N],q[]=new int[N*N],v[]={-N,N,-1,1},h=0,t=1;for(j=i++;j-->0;)b[B[j]]=1;b[0]=1;x:for(int S=z=0,E;h<t;S++)for(E=t;h<E;){int p=q[h++];if(p>N*N-2){z=S;break x;}for(int d:v){d+=p;if(d>=0&d<N*N&&Math.abs(d%N-p%N)<2&b[d]<1)b[q[t++]=d]=1;}}}while(z>0&!P);return P?""+z:B[i-2]%N+","+B[i-2]/N;}}
